}
addEventListener('storage',function(e){if(e.key===KEY||e.key==='nk-conn-1'){var a=d.activeElement,keep=a&&a.id==='ms-in'?a.value:null;render();if(keep!=null){var n=$('#ms-in');if(n){n.value=keep;n.focus()}}}});
